import logging
from taf.converters.pmtocsv.factory import PmToCsvConverterFactory
from taf.converters.base import base

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class pmtocsv(base):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def create_pm_to_csv_converter(
            self,
            name,
            file_path_pattern,
            delimiter=None,
            output_file_name=None,
            nidd_path=None):
        """
        Create a converter to convert PM files from XML to CSV format.

        PM files created by gNB contain PM-counters. These PM files are hard to handle in automatic tests.
        To ease automatic tests conversion to a CSV file is done by this keyword in conjunction with the "convert" keyword.

        :param str name: name of the converter
        :param str file_path_pattern: file paths (wildcards allowed, e. g.: "\\*_PM_*.xml" or "\\*/PM\\*20190714*.xml".)
        :param str delimiter: delimiter character e. g. "," or ";" default is ";"
        :param str output_file_name: name of output file. default is "Pm.csv"
        :param str nidd_path: NIDD PM metadata XML file (optional)

        .. code-block:: robotframework

            *Test Case*
            testcase1
                Create PM to CSV converter
                ...  name=test converter
                ...  file_path_pattern=test/resources/*_PM_*
                ...  delimiter=;
                ...  output_file_name=Pm.csv
                ...  nidd_path=resources/pmcounters/Counters_5G19A.xml

                Convert  test converter
        """
        logger.info("Creating Converter with alias:" + name)
        existing_arguments = {}
        configuration = {
            "file_path_pattern": file_path_pattern}
        if delimiter is not None:
            configuration["delimiter"] = str(delimiter)
        if output_file_name is not None:
            configuration["output_file_name"] = output_file_name
        if nidd_path is not None:
            configuration["nidd_path"] = nidd_path
        converter = PmToCsvConverterFactory().create(configuration=configuration, existing_arguments=existing_arguments)
        logger.info(name + " converter created successfully")
        self.set_alias(name, converter)
